/* main.c -- standalone music player ROM (gbc-music skill, built by song_rom.py).
 *
 * No game: the ROM boots straight into song 1 and shows a text screen (player name, song title, song N/M, the
 * score's bars / bpm, a live BAR / ROW counter from music_bar() / music_row()). Controls:
 *   START  next song      SELECT  previous song      A  restart the song      B  duck / unduck (music_set_volume 6 / 15)
 * The same driver (music.c / music.h) and the same compiled tables (music_data.c, from compose.py compile) a game
 * ships with; songs.h is generated by song_rom.py (SONG_COUNT, song_table[], song_titles[], song_infos[]).
 *
 * The APU is powered here exactly as a game's sfx_init() does (NR52 on, NR50 full, then music_set_pan_base(0xFF):
 * every channel to both speakers; the driver owns NR51 from then on and the game never writes it directly). */
#include <gb/gb.h>
#include <gb/cgb.h>
#include <gb/hardware.h>
#include <stdint.h>
#include <string.h>

#include "music.h"
#include "music_data.h"
#include "songs.h"

/* 48 1bpp glyphs (space, 0-9, A-Z, . ! : - > ? , / ' + *) in BG tiles 0..47. Data only: no dependency on a game font. */
