/* dark panel, two mids, cream ink */
static const palette_color_t pal_text[4] = { RGB8(16, 24, 48), RGB8(72, 88, 128), RGB8(160, 176, 208), RGB8(248, 248, 232) };
static const palette_color_t pal_dim[4]  = { RGB8(16, 24, 48), RGB8(40, 56, 96),  RGB8(96, 112, 152),  RGB8(160, 176, 208) };

static uint8_t tile_buf[20];
static uint8_t attr_buf[20];
static uint8_t cur_song;
static uint8_t ducked;
static uint8_t joy_now, joy_prev;
static char line[21];

static uint8_t glyph(char c) {
    if (c >= 'a' && c <= 'z') c = (char)(c - 'a' + 'A');
    if (c == ' ') return 0;
    if (c >= '0' && c <= '9') return (uint8_t)(1 + (c - '0'));
    if (c >= 'A' && c <= 'Z') return (uint8_t)(11 + (c - 'A'));
    switch (c) {
        case '.': return 37;  case '!': return 38;  case ':': return 39;  case '-': return 40;
        case '>': return 41;  case '?': return 42;  case ',': return 43;  case '/': return 44;
        case '\'': return 45; case '+': return 46;  case '*': return 47;
        default: return 42;
    }
}

/* Draw `s` centred in the 20-tile row y, padded with spaces, on palette `pal`. */
static void text_row(uint8_t y, const char *s, uint8_t pal) {
    uint8_t n = 0, pad, i;
    while (s[n] && n < 20) n++;
    pad = (uint8_t)((20 - n) >> 1);
    for (i = 0; i < 20; i++) tile_buf[i] = 0;
    for (i = 0; i < n; i++) tile_buf[pad + i] = glyph(s[i]);
    memset(attr_buf, pal, 20);
    set_bkg_tiles(0, y, 20, 1, tile_buf);
    set_bkg_attributes(0, y, 20, 1, attr_buf);
}

static void two_digits(char *out, uint8_t v) {
    out[0] = (char)('0' + (v / 10) % 10);
    out[1] = (char)('0' + v % 10);
}

static void draw_static(void) {
    text_row(1, PLAYER_TITLE, 0);
    text_row(2, "--------------------", 1);
    text_row(5, song_titles[cur_song], 0);
    strcpy(line, "SONG 0/0");
    line[5] = (char)('1' + cur_song);
    line[7] = (char)('0' + SONG_COUNT);
    text_row(7, line, 1);
    text_row(9, song_infos[cur_song], 1);
    text_row(14, "START NEXT SEL PREV", 1);
    text_row(15, "A RESTART  B DUCK", 1);
}

static void draw_counter(void) {
    strcpy(line, "BAR 00  ROW 00");
    two_digits(line + 4, (uint8_t)(music_bar() + 1));
    two_digits(line + 12, music_row());
    text_row(11, line, 0);
}

static void start_song(uint8_t i) {
    cur_song = i;
    music_init(song_table[cur_song]);
    music_set_volume(ducked ? 6 : 15);
    draw_static();
}

static void apu_init(void) {
    NR52_REG = 0x80;  /* APU on (must be first) */
    NR50_REG = 0x77;  /* master volume L/R = 7 */
    music_set_pan_base(0xFF);  /* every channel to both outputs; the driver owns NR51 from here */
}

void main(void) {
    uint8_t pressed;
    if (_cpu == CGB_TYPE) cpu_fast();
    DISPLAY_OFF;
    apu_init();
    set_1bpp_colors(3, 0);
    set_bkg_1bpp_data(0, GLYPHS, font_1bpp);
    set_bkg_palette(0, 1, pal_text);
    set_bkg_palette(1, 1, pal_dim);
    fill_bkg_rect(0, 0, 20, 18, 0);
    SHOW_BKG;
    DISPLAY_ON;
    start_song(0);

    while (1) {
        joy_prev = joy_now;
        joy_now = joypad();
        pressed = (uint8_t)(joy_now & (uint8_t)~joy_prev);
        if (pressed & J_START) start_song((uint8_t)((cur_song + 1) % SONG_COUNT));
        else if (pressed & J_SELECT) start_song((uint8_t)((cur_song + SONG_COUNT - 1) % SONG_COUNT));
        else if (pressed & J_A) start_song(cur_song);
        else if (pressed & J_B) { ducked = (uint8_t)!ducked; music_set_volume(ducked ? 6 : 15); }
        draw_counter();
        wait_vbl_done();
        music_tick();
    }
}
